<?php
require_once __DIR__ . '/assets/php/bootstrap.php';
$products=[];$categories=[];$error=null;
try {$products=db()->query('SELECT p.id_producto,p.nombre,p.precio,p.imagen,c.nombre categoria FROM producto p JOIN categoria_producto c ON c.id_categoria=p.categoria_id WHERE p.activo=TRUE AND p.stock>0 ORDER BY p.fecha_actualizacion DESC')->fetchAll();$categories=db()->query('SELECT c.nombre,COUNT(p.id_producto) total FROM categoria_producto c LEFT JOIN producto p ON p.categoria_id=c.id_categoria AND p.activo=TRUE AND p.stock>0 GROUP BY c.id_categoria ORDER BY c.nombre')->fetchAll();} catch(Throwable){$error='No fue posible cargar el catálogo.';}
?>
